                kategori : 'UMUM',
                harga : 'Rp500.000'
            },

            utara : {
                nama : 'Tribun Utara',
                kategori : 'UMUM',
                harga : 'Rp500.000'
            },

            selatan : {
                nama : 'Tribun Selatan',
                kategori : 'UMUM',
                harga : 'Rp500.000'
            },

            kat1utara : {
                nama : 'Tribun Kategori 1 Utara',
                kategori : 'KATEGORI 1',
                harga : 'Rp750.000'
            },

            kat1selatan : {
                nama : 'Tribun Kategori 1 Selatan',
                kategori : 'KATEGORI 1',
                harga : 'Rp750.000'
            },

            vipbarat : {
                nama : 'Tribun VIP',
                kategori : 'VIP',
                harga : 'Rp1.000.000'
            },

            vvipbarat : {
                nama : 'Tribun VVIP',
                kategori : 'VVIP',
                harga : 'Rp2.000.000'
            }

        };

        Object.keys(dataTribun).forEach(function(id){

            const tribun = document.getElementById(id);

            if(tribun){

                tribun.addEventListener('click', function(){

                    document.getElementById('tribunNama').innerText =
                        dataTribun[id].nama;

                    document.getElementById('tribunKategori').innerText =
                        dataTribun[id].kategori;

                    document.getElementById('tribunHarga').innerText =
                        dataTribun[id].harga;

                    document.getElementById('btnLanjut').disabled = false;

                    document.querySelectorAll('.tribun-selected')
                        .forEach(el => el.classList.remove('tribun-selected'));

                    this.classList.add('tribun-selected');

                    const eventId = {{ $event->id_event }};

                    document.getElementById('btnLanjut').href =
                        `/event/${eventId}/tribun/${id}/blok`;

                    document.getElementById('btnLanjut')
                        .classList.remove('disabled');


                });

                // const eventId = {{ $event->id_event }};

                //     document.getElementById('btnLanjut').href =
                //         `/event/${eventId}/tribun/${id}/blok`;

                //     document.getElementById('btnLanjut')
                //         .classList.remove('disabled');

            }

        });

    });
</script>
